(function() {
  const slider = document.getElementById('snr-slider');
  const snrValDisplay = document.getElementById('snr-val');
  const valLower = document.getElementById('val-lower');
  const valUpper = document.getElementById('val-upper');
  const valGap = document.getElementById('val-gap');
  const canvas = document.getElementById('bound-canvas');
  const ctx = canvas.getContext('2d');

  // Constants
  const W = 1; // Normalized bandwidth
  const N = 1; // Normalized noise
  const PI = Math.PI;
  const E = Math.E;

  // Formulas based on specific corrections:
  // Lower Bound (Theorem 20): C >= W * log2( (2 / (PI * E^3)) * (S/N) )
  // We ensure the argument to log is at least 1 to avoid negative capacity in demo for very low SNR
  // Upper Bound (Reference): C <= W * log2(1 + S/N) (Average Power Constraint)

  function calculateBounds(snr) {
    const r = snr; // S/N ratio
    const log2 = (x) => Math.log(x) / Math.log(2);

    // Lower Bound Calculation
    const constantFactor = 2 / (PI * Math.pow(E, 3));
    const lowerArg = constantFactor * r;
    // Capacity cannot be negative in this context, clamp arg to 1 if needed for visualization stability
    const lower = W * log2(Math.max(1, lowerArg));

    // Upper Bound Calculation (Average Power Reference)
    const upper = W * log2(1 + r);

    return { lower: lower, upper: upper, gap: upper - lower };
  }

  function drawChart(snr) {
    const width = canvas.width;
    const height = canvas.height;
    const padding = 50;

    // Clear
    ctx.clearRect(0, 0, width, height);

    // Draw Axes
    ctx.beginPath();
    ctx.strokeStyle = '#1a2b4a';
    ctx.lineWidth = 2;
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // Labels
    ctx.fillStyle = '#1a2b4a';
    ctx.font = '14px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('S/N (Linear)', width / 2, height - 15);
    ctx.save();
    ctx.translate(20, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('Capacity (W=1)', 0, 0);
    ctx.restore();

    // Plot Curves
    const maxSNR = 100;
    const boundsData = [];

    for (let s = 1; s <= maxSNR; s++) {
      const b = calculateBounds(s);
      boundsData.push({ snr: s, lower: b.lower, upper: b.upper });
    }

    // Scale
    const maxX = maxSNR;
    // Find max Y dynamically to ensure curves fit
    const maxY = Math.max(...boundsData.map(d => d.upper)) * 1.1;

    const xScale = (width - 2 * padding) / maxX;
    const yScale = (height - 2 * padding) / maxY;

    const getX = (val) => padding + val * xScale;
    const getY = (val) => height - padding - val * yScale;

    // Draw Upper Bound (Reference)
    ctx.beginPath();
    ctx.strokeStyle = '#d35400'; // Warm color
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 3]);
    boundsData.forEach((d, i) => {
      if (i === 0) ctx.moveTo(getX(d.snr), getY(d.upper));
      else ctx.lineTo(getX(d.snr), getY(d.upper));
    });
    ctx.stroke();
    ctx.setLineDash([]);

    // Draw Lower Bound (Theorem 20)
    ctx.beginPath();
    ctx.strokeStyle = '#007acc'; // Accent color
    ctx.lineWidth = 2;
    boundsData.forEach((d, i) => {
      if (i === 0) ctx.moveTo(getX(d.snr), getY(d.lower));
      else ctx.lineTo(getX(d.snr), getY(d.lower));
    });
    ctx.stroke();

    // Fill Area between curves
    ctx.beginPath();
    ctx.fillStyle = 'rgba(0, 122, 204, 0.1)';
    ctx.moveTo(getX(boundsData[0].snr), getY(boundsData[0].lower));
    boundsData.forEach(d => ctx.lineTo(getX(d.snr), getY(d.lower)));
    for (let i = boundsData.length - 1; i >= 0; i--) {
      ctx.lineTo(getX(boundsData[i].snr), getY(boundsData[i].upper));
    }
    ctx.closePath();
    ctx.fill();

    // Draw Current Point
    const currentBounds = calculateBounds(snr);
    const cx = getX(snr);
    const cyLower = getY(currentBounds.lower);
    const cyUpper = getY(currentBounds.upper);

    ctx.fillStyle = '#1a2b4a';
    ctx.beginPath();
    ctx.arc(cx, cyLower, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(cx, cyUpper, 6, 0, Math.PI * 2);
    ctx.fill();

    // Connector Line
    ctx.beginPath();
    ctx.strokeStyle = '#1a2b4a';
    ctx.lineWidth = 1;
    ctx.setLineDash([2, 2]);
    ctx.moveTo(cx, cyLower);
    ctx.lineTo(cx, cyUpper);
    ctx.stroke();
    ctx.setLineDash([]);

    // Legend
    ctx.fillStyle = '#d35400';
    ctx.fillRect(width - 180, 20, 15, 2);
    ctx.fillStyle = '#1a2b4a';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('Ref: Avg Power Upper', width - 160, 24);

    ctx.fillStyle = '#007acc';
    ctx.fillRect(width - 180, 40, 15, 2);
    ctx.fillStyle = '#1a2b4a';
    ctx.fillText('Thm 20 Lower Bound', width - 160, 44);
  }

  function update() {
    const snr = parseInt(slider.value, 10);
    snrValDisplay.textContent = snr;

    const bounds = calculateBounds(snr);

    // Update Text Stats with data-value attributes
    valLower.textContent = bounds.lower.toFixed(3) + ' W';
    valLower.setAttribute('data-value', bounds.lower.toFixed(3));

    valUpper.textContent = bounds.upper.toFixed(3) + ' W';
    valUpper.setAttribute('data-value', bounds.upper.toFixed(3));

    valGap.textContent = bounds.gap.toFixed(3) + ' W';
    valGap.setAttribute('data-values', bounds.lower.toFixed(3) + ',' + bounds.upper.toFixed(3));

    drawChart(snr);
  }

  slider.addEventListener('input', update);

  // Initial Draw
  update();
})();
